import java.util.List;
import java.util.stream.Collectors;

interface Performance {
    void perform();
}

class Actor implements Performance {
    private String name;

    public Actor(String name) {
        this.name = name;
    }

    @Override
    public void perform() {
        System.out.println(name + " takes the stage.");
    }
}

public class GrandFinale {
    public static void main(String[] args) {
        List<Performance> cast = new ArrayList<>();

        cast.add(new Actor("The King"));
        cast.add(new Actor("The Queen"));
        cast.add(() -> System.out.println("The Orchestra performs."));
        cast.add(() -> System.out.println("The Confetti Cannon erupts."));

