import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class GoodJdbcExample {

    public static void main(String[] args) {
        // Simulating a web application receiving user input
        String userInput = "admin' OR '1'='1";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass")) {

            // SECURE: Using PreparedStatement with parameterized queries
