import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class SafeOutputServlet extends HttpServlet {

    // Fixed: use a controlled base directory and Java NIO instead of OS commands
    private static final Path BASE_DIR = Path.of("/tmp/safe-output").toAbsolutePath().normalize();

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // User-controlled input from the query string
        String fileName = request.getParameter("file");

        // Fixed: validate input and reject anything that is not a simple file name
        if (fileName == null || !fileName.matches("[a-zA-Z0-9._-]+")) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST);
            return;
        }

        // Fixed: resolve and normalize the path to prevent path traversal
        Path target = BASE_DIR.resolve(fileName).normalize();

        // Fixed: ensure the resolved path stays inside the allowed directory
        if (!target.startsWith(BASE_DIR) || !Files.isRegularFile(target)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND);
            return;
        }

        // Fixed: use a safe Java API to read the file contents
        List<String> lines = Files.readAllLines(target);
        for (String line : lines) {
            response.getWriter().println(line);
        }
    }
}
