    },
    "criteria": [
      {
        "category": "Technical Proficiency",
        "weight": 20,
        "description": "Depth and application of programming, systems, and domain knowledge.",
        "levels": {
          "1": "Applies fundamental concepts incorrectly and produces work with frequent technical errors.",
          "2": "Has basic knowledge but requires substantial guidance to use tools, frameworks, or patterns effectively.",
          "3": "Demonstrates solid technical knowledge and applies appropriate practices to solve common problems independently.",
          "4": "Shows advanced knowledge, evaluates technical trade-offs, and helps others make better technical decisions.",
          "5": "Demonstrates expert-level knowledge, solves complex novel problems, and establishes technical standards for the team."
        }
      },
      {
        "category": "Code Quality and Maintainability",
        "weight": 20,
        "description": "Clarity, reliability, testability, and long-term maintainability of code.",
        "levels": {
          "1": "Code is difficult to understand, fragile, or requires frequent rework.",
          "2": "Code works but is inconsistent, underdocumented, or hard to maintain without assistance.",
          "3": "Code is clean, readable, and follows team standards with appropriate documentation.",
          "4": "Code is high quality, robust, and often improves the surrounding codebase through good design.",
          "5": "Code sets a quality standard, demonstrates elegant solutions, and proactively improves long-term maintainability."
        }
      },
      {
        "category": "System Design and Architecture",
        "weight": 15,
        "description": "Ability to design systems that meet functional and non-functional requirements.",
        "levels": {
          "1": "Struggles to understand system boundaries, components, or design requirements.",
          "2": "Participates in design with guidance but requires support for meaningful decisions.",
          "3": "Designs straightforward systems that satisfy requirements and considers basic constraints.",
          "4": "Designs scalable, resilient systems while balancing trade-offs such as performance, cost, and complexity.",
          "5": "Designs complex systems with strong architectural judgment, anticipates failure modes, and influences long-term system direction."
        }
      },
      {
        "category": "Testing and Quality Assurance",
        "weight": 10,
        "description": "Ownership of correctness, testing practices, and defect prevention.",
        "levels": {
          "1": "Writes little or no effective testing and allows frequent defects to reach downstream environments.",
          "2": "Provides basic tests but lacks consistency, coverage, or ownership of quality.",
          "3": "Writes appropriate tests, verifies changes effectively, and addresses defects in a timely way.",
          "4": "Improves test coverage and quality, identifies risky areas, and helps establish better testing practices.",
          "5": "Champions quality across the team, builds robust testing strategies, and proactively prevents defects."
        }
      },
      {
        "category": "Delivery and Reliability",
        "weight": 10,
        "description": "Ability to estimate, commit to, and deliver work reliably.",
        "levels": {
          "1": "Frequently misses commitments and requires repeated follow-up.",
          "2": "Delivers work with significant assistance and may need reminders to maintain progress.",
          "3": "Delivers committed work reliably and communicates status, blockers, and risks clearly.",
          "4": "Consistently meets or exceeds commitments, anticipates risks, and helps keep teams on track.",
          "5": "Demonstrates exceptional reliability, drives outcomes under ambiguity, and enables others to deliver predictably."
        }
      },
      {
        "category": "Problem Solving and Debugging",
        "weight": 10,
        "description": "Ability to analyze, diagnose, and resolve technical issues effectively.",
        "levels": {
          "1": "Has difficulty breaking down problems and often requires significant help to identify root causes.",
          "2": "Can solve familiar issues with guidance but has limited ability to investigate unfamiliar problems.",
          "3": "Breaks down problems effectively, debugs common issues independently, and implements workable fixes.",
          "4": "Analyzes complex problems, identifies root causes, and evaluates multiple solution paths.",
          "5": "Tackles highly ambiguous or complex problems, creates scalable fixes, and improves team problem-solving approaches."
        }
      },
      {
        "category": "Collaboration and Communication",
        "weight": 10,
        "description": "Ability to collaborate, communicate clearly, and contribute to team health.",
        "levels": {
          "1": "Collaborates poorly, communicates unclearly, and does not respond well to feedback.",
          "2": "Participates inconsistently and may require clarification to communicate status or decisions.",
          "3": "Collaborates effectively, communicates clearly, and responds constructively to feedback.",
          "4": "Builds trust, shares knowledge proactively, and communicates trade-offs to both technical and non-technical stakeholders.",
          "5": "Strongly influences team collaboration, resolves conflicts, and communicates with clarity, empathy, and impact."
        }
      },
      {
        "category": "Ownership and Initiative",
        "weight": 5,
        "description": "Level of responsibility, follow-through, and proactive contribution.",
        "levels": {
          "1": "Takes minimal ownership, waits for direction, and avoids responsibility for outcomes.",
          "2": "Takes some ownership but requires prompts and has inconsistent follow-through.",
          "3": "Owns assigned work, follows through, and looks for ways to improve processes or outcomes.",
          "4": "Proactively identifies gaps, drives improvements, and supports teammates beyond assigned tasks.",
          "5": "Demonstrates exceptional ownership, leads by example, and has meaningful impact on team and product success."
        }
      }
    ],
    "scoring_instructions": [
      "Score each category from 1 to 5 based on observed performance over the review period.",
      "Use concrete evidence such as pull requests, design documents, code reviews, incident response, deployment outcomes, and peer feedback.",
      "Calculate an overall weighted score by multiplying each category score by its weight and summing the results; the total possible weighted score is 500."
    ],
    "calibration_guidance": "Compare candidates against the same level expectations and avoid bias from visibility, project type, or seniority."
  }
}

