final_answer:
{
  "startup_pitch": {
    "startup_name": "Tipperary",
    "tagline": "Know what to tip. Confidently. Every time.",
    "one_liner": "Tipperary is the app that tells you the average tip size for any restaurant, so diners, servers, and hospitality businesses can reduce tipping ambiguity and improve service experience.",
    "executive_summary": "Tipping is culturally important but inconsistent. Customers often feel unsure whether a 15%, 18%, 20%, or larger tip is appropriate for a given restaurant, and that uncertainty can affect customer satisfaction, server income, and brand perception. Tipperary solves this by providing a simple, location-based tipping intelligence layer that shows the average tip size for each restaurant. The app turns ambiguous tipping norms into clear, actionable data.",
    "problem": {
      "title": "Tipping is confusing and inconsistent",
      "points": [
        "Diners often do not know what tip percentage is expected at a specific restaurant.",
        "Tipping norms vary by city, neighborhood, restaurant type, check size, service model, and local culture.",
        "Uncertainty can lead to under-tipping, over-tipping, awkwardness, or frustration.",
        "Servers and managers lack visibility into customer tipping expectations, which can create inconsistent service quality.",
        "Restaurants lose an opportunity to set clearer service expectations and improve overall guest experience."
      ]
    },
    "solution": {
      "title": "A tipping intelligence app for every restaurant",
      "description": "Tipperary aggregates verified tipping data from diners, public reviews, restaurant metadata, and service signals to calculate the average tip size for each restaurant. Users can search a restaurant by name, QR code, table number, or location and instantly see the typical tip range, recommended tip, and how that restaurant compares to nearby competitors.",
      "core_features": [
        {
          "feature": "Restaurant tip profile",
          "description": "Shows average tip percentage, typical dollar amount, tip range, and confidence level based on available data."
        },
        {
          "feature": "QR code tipping lookup",
          "description": "Restaurants can place Tipperary QR codes on menus or tables so guests can scan and see the average tip before paying."
        },
        {
          "feature": "Anonymous data contribution",
          "description": "Diners can optionally submit their actual tip after the meal, improving data accuracy and network effects."
        },
        {
          "feature": "Location-aware tips",
          "description": "Tipperary factors in city, restaurant category, price point, and local tipping culture to provide more relevant recommendations."
        },
        {
          "feature": "Server and restaurant dashboard",
          "description": "Restaurants can see average reported tips, compare performance, and understand customer sentiment around service and pricing."
        }
      ]
    },
    "market": {
      "target_users": [
        "Diners who want to tip appropriately without awkward guesswork",
        "Tourists and business travelers unfamiliar with local tipping customs",
        "Restaurants that want to improve guest experience and service consistency",
        "Servers and hospitality managers who benefit from clearer tipping expectations",
        "Payment and restaurant technology platforms seeking value-added tools"
      ],
      "market_opportunity": "The opportunity is large because tipping is a universal behavior in the food service industry but lacks a standard, restaurant-specific reference point. Every sit-down restaurant, fast-casual establishment with optional tipping, bar, cafe, and delivery-adjacent service experience can benefit from a shared tipping benchmark."
    },
    "value_proposition": {
      "for_customers": "Remove guessing and social anxiety. Tip with confidence, transparency, and consistency.",
      "for_restaurants": "Increase service clarity, improve guest satisfaction, and gain useful feedback on perceived service quality.",
      "for_servers": "Reduce tipping variability and create a clearer relationship between effort, quality, and recognition.",
      "for_investors": "Tipperary builds a data network in a high-frequency consumer behavior, with clear monetization, strong brand potential, and expansion into adjacent hospitality services."
    },
    "competitive_advantage": {
      "title": "Why Tipperary wins",
      "points": [
        "First-mover potential in restaurant-specific tipping intelligence.",
        "Data network effects: the more diners use and contribute, the more accurate and valuable the app becomes.",
        "Low-friction consumer utility: users only need to check a restaurant and get an immediate answer.",
        "B2B2C distribution: restaurants can place QR codes and in-app integrations, driving organic adoption.",
        "Unique dataset: Tipperary combines user-submitted tip data, restaurant metadata, review sentiment, and geographic behavior to create a proprietary benchmark."
      ]
    },
    "product_roadmap": [
      {
        "phase": "MVP",
        "focus": "iOS and Android app with restaurant search, average tip lookup, user-submitted tip data, and manual onboarding for restaurants."
      },
      {
        "phase": "Growth",
        "focus": "QR code scanning, city-level tipping maps, anonymous data collection, and restaurant dashboards."
      },
      {
        "phase": "Scale",
        "focus": "Restaurant platform integrations, API access, payment provider partnerships, and tipping insights for operators."
      }
    ],
    "business_model": {
      "revenue_streams": [
        "B2B SaaS for restaurants, including dashboard access, QR codes, tipping benchmark reports, and performance insights",
        "Premium consumer subscriptions for advanced features such as tipping history, personalized recommendations, and cross-city travel tools",
        "Data licensing and API access for payment companies, hospitality platforms, and restaurant management systems",
        "Optional sponsored insights, provided in a transparent and non-manipulative way"
      ],
      "pricing_hypothesis": [
        "Free tier for consumers: basic average tip lookup per restaurant",
        "Premium consumer tier: $2.99/month or $24.99/year for advanced tools",
        "Restaurant tier: $49-$199/month depending on location, size, and data depth",
        "Enterprise/API tier: custom pricing for multi-location restaurant groups and technology partners"
      ]
    },
    "go_to_market": [
      "Launch in one high-traffic metropolitan area with strong dining culture",
      "Recruit 200 restaurants using QR codes and owner partnerships",
      "Drive consumer adoption through social media, food influencers, restaurant partnerships, and local press",
      "Integrate with restaurant reservation and payment platforms",
      "Expand city by city using a data flywheel: more restaurants = more accurate tips = more user trust = more data"
    ],
    "key_metrics": {
      "consumer_metrics": [
        "Monthly active users",
        "Restaurants looked up per user per week",
        "Tip submissions per active user",
        "Retention and repeat usage rate"
      ],
      "restaurant_metrics": [
        "Number of active restaurant partners",
        "QR code scans per restaurant",
        "Dashboard engagement",
        "Average reported tip percentage",
        "Customer satisfaction correlation with reported tips"
      ],
      "data_quality_metrics": [
        "Number of verified tip data points per restaurant",
        "Confidence score for each average",
        "Data refresh rate",
        "Outlier detection accuracy"
      ]
    },
    "financial_summary": {
      "initial_use_of_funds": [
        "Product development",
        "Mobile app infrastructure",
        "Restaurant sales and partnerships",
        "Marketing and user acquisition",
        "Data modeling and analytics"
      ],
      "12_month_goal": "Reach 100,000 consumer users, 1,000 restaurant partners, and generate early B2B revenue through restaurant subscriptions and pilot API contracts."
    },
    "ask": {
      "title": "Investment ask",
      "amount": "$500,000",
      "round": "Seed",
      "use": "To build the MVP, launch in one major metro, acquire 1,000 restaurant partners, and establish a defensible tipping data network.",
      "target_outcomes": [
        "Live iOS and Android apps",
        "QR code integration for restaurants",
        "Minimum viable tipping dataset for 5,000 restaurants",
        "Early B2B revenue and repeat consumer usage"
      ]
    },
    "closing_message": "Tipperary turns an everyday moment of uncertainty into a simple, trusted answer. The app is not just about telling people what to tip; it is about creating a clearer, more confident, and more positive experience for diners, servers, and restaurants. With the right data network and distribution, Tipperary can become the standard reference for tipping in the restaurant industry."
  }
}

