<script>
(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var items = Array.prototype.slice.call(document.querySelectorAll('.lim'));

  /* ticker fill (two identical halves for a seamless loop) */
  var names = "BILL ✦ BILLY ✦ WILLIAM ✦ WILBUR ✦ WILHELM ✦ BILL THE THIRD ✦ MR. WILL ✦ OLD BILL ✦ YOUNG BILL ✦ DR. BILL ✦ BILL JR. ✦ THE GREAT BILL ✦ BILLY RAGS ✦ BILL THE BRILLIANT ✦ A BILL OF MIRTH ✦ ";
  var seq = '<span class="tt">' + names.replace(/BILL\b/g,'<b>BILL</b>') + '</span>';
  document.getElementById('track').innerHTML = seq + seq;

  /* scroll reveal with per-line cascade */
  if (reduce || !('IntersectionObserver' in window)) {
    items.forEach(function(el){ el.classList.add('in'); });
  } else {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
      });
    }, { threshold:.16, rootMargin:'0px 0px -8% 0px' });
    items.forEach(function(el){ io.observe(el); });

    /* now-reading chip */
    var now = document.getElementById('now');
    var io2 = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting){
          var no = e.target.querySelector('.no').textContent;
          var cap = e.target.querySelector('.cap').textContent;
          now.innerHTML = '<span class="lbl">Now reading</span> <b>Nº ' + no + '</b> <span class="c">' + cap + '</span>';
        }
      });
    }, { rootMargin:'-45% 0px -45% 0px', threshold:0 });
    items.forEach(function(el){ io2.observe(el); });
  }

  /* progress + watermark parallax */
  var bar = document.getElementById('progress'), wm = document.getElementById('wm'), tick = false;
  function onScroll(){
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';
    if (!reduce) wm.style.transform = 'translateY(' + (h.scrollTop * -0.05) + 'px)';
    tick = false;
  }
  window.addEventListener('scroll', function(){ if(!tick){ requestAnimationFrame(onScroll); tick = true; } }, { passive:true });
  onScroll();

  /* deal me a Bill */
  var deal = document.getElementById('deal'), dealt = document.getElementById('dealt');
  var count = 0, now = document.getElementById('now');
  deal.addEventListener('click', function(){
    count++; dealt.textContent = count;
    var i = Math.floor(Math.random() * items.length);
    var el = items[i];
    if (now) now.innerHTML = '<span class="lbl">Now reading</span> <b>Nº ' + el.querySelector('.no').textContent + '</b> <span class="c">' + el.querySelector('.cap').textContent + '</span>';
    el.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'center' });
    setTimeout(function(){
      document.querySelectorAll('.lim.picked').forEach(function(x){ if (x !== el) x.classList.remove('picked'); });
      el.classList.remove('picked'); void el.offsetWidth; el.classList.add('picked');
      setTimeout(function(){ el.classList.remove('picked'); }, 1600);
    }, reduce ? 0 : 420);
  });
})();
</script>
</body>
