  .tag{ position:absolute; top:.5rem; right:.55rem; font-family:var(--mono); font-weight:700; font-size:.6rem;
    letter-spacing:.12em; text-transform:uppercase; color:var(--red); border:2px solid var(--red); padding:.14rem .4rem;
    transform:rotate(-8deg) scale(0); transition:transform .35s var(--ease); }
  .lim.picked .tag{ transform:rotate(-8deg) scale(1); }
  .lim.picked{ animation:flash 1.5s var(--ease); }
  @keyframes flash{ 0%{background:transparent} 16%{background:rgba(192,51,31,.16); box-shadow:0 0 0 3px var(--red)} 100%{background:transparent; box-shadow:0 0 0 0 transparent} }

  /* now reading chip */
  .now{ position:fixed; left:1rem; bottom:1rem; z-index:50; display:flex; align-items:center; gap:.55rem;
    background:var(--ink); color:var(--paper); padding:.55rem .8rem; border:2px solid var(--red);
    box-shadow:4px 4px 0 rgba(0,0,0,.4); font-family:var(--mono); font-size:.72rem; letter-spacing:.1em; text-transform:uppercase; }
  .now .lbl{ color:var(--paper); opacity:.7; }
  .now b{ color:var(--red); }
  .now .c{ color:var(--gold); }

  /* colophon */
  .colo{ margin-top:1.8rem; }
  .colo-text{ font-family:var(--mono); font-size:.72rem; letter-spacing:.06em; line-height:1.9; text-transform:lowercase;
    color:var(--ink-soft); margin:.9rem 0 0; }
  .colo-text .fin{ display:block; text-align:center; color:var(--red); font-weight:700; letter-spacing:.3em; text-transform:uppercase; margin-bottom:.6rem; }
  .colo-text .k{ color:var(--red); font-weight:700; }

  @media (max-width:1180px){ .grid{ column-count:2 } }
  @media (max-width:660px){
    .grid{ column-count:1 }
    .now{ display:none }
    .sign{ text-align:left }
    .mast-stamp{ order:-1 }
  }
  @media (prefers-reduced-motion: reduce){
    *{ animation:none !important; transition:none !important }
    .lim,.lim .l,.mast-text,.mast-stamp,.controls,.sheet{ opacity:1 !important; transform:none !important }
    .ticker-track{ animation:none }
  }
</style>
</head>
<body>
  <div class="progress" id="progress"></div>
  <div class="wm" id="wm" aria-hidden="true">B</div>

  <div class="ticker" aria-hidden="true">
    <div class="ticker-track" id="track"></div>
  </div>

  <main class="sheet">
    <div class="grain" aria-hidden="true"></div>

    <header class="mast">
      <div class="mast-top">
        <span>Broadside No. 25</span>
        <span class="mid">A Bill of Mirth</span>
        <span>Price 6d · Pay in Laughter</span>
      </div>

      <div class="mast-grid">
        <div class="mast-text">
          <p class="overline">A broadside in print · twenty-five verses · one name</p>
          <h1 class="mast-title">The <span class="hi">Bill</span><br>Almanack</h1>
          <p class="dek">Being a complete <em>bill</em> of mirth upon one gentleman, variously christened Bill,
            Billy, William &amp; Wilbur — set down in fair ink by an amateur <em>economist</em>, and first recited,
            to a roaring room, by a certain Herr <em>Jurgen</em> at the Green Anchor.</p>
          <p class="sign">— the printer's note</p>
        </div>

        <div class="mast-stamp">
          <svg class="stamp" viewBox="0 0 200 200" aria-hidden="true">
            <circle class="s-o" cx="100" cy="100" r="95"/>
            <circle class="s-d" cx="100" cy="100" r="86"/>
            <circle class="s-i" cx="100" cy="100" r="52"/>
            <g class="ring">
              <defs><path id="sp" d="M100,100 m-69,0 a69,69 0 1,1 138,0 a69,69 0 1,1 -138,0"/></defs>
              <text class="s-t"><textPath href="#sp" startOffset="0">A BILL OF MIRTH · 25 VERSES · PAY IN LAUGHTER ·</textPath></text>
            </g>
            <text class="s-c" x="100" y="104" text-anchor="middle">25</text>
            <text class="s-s" x="100" y="134" text-anchor="middle">BILLS</text>
          </svg>
        </div>
      </div>
    </header>

    <div class="fleuron" aria-hidden="true"><span>❦</span></div>

    <div class="controls">
      <p class="meta"><b>25</b> bills · <b>1</b> subject · <b>0</b> apologies</p>
      <button class="deal" id="deal">✦ Deal me a Bill</button>
      <span class="dealt">bills dealt: <b id="dealt">0</b></span>
    </div>

    <ol class="grid" id="grid" role="list">
      <li class="lim">
        <div class="lim-head"><span class="no">01</span><span class="cap">the economist (and Herr Jurgen)</span></div>
        <div class="verse">
          <span class="l">There was an economist, Bill,</span>
          <span class="l">Who sketched his supply curves on the sill;</span>
          <span class="l">Young Jurgen cried, “Crash!”</span>
          <span class="l">Bill replied, “I’m in cash,”</span>
          <span class="l">Hedged his bets — and made bank, you could tell.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">02</span><span class="cap">the whistler</span></div>
        <div class="verse">
          <span class="l">There was a young man from Bristol named Bill,</span>
          <span class="l">Who whistled a tune for the kettle to fill;</span>
          <span class="l">The kettle screeched back,</span>
          <span class="l">Bill said, “That’s a knack —”</span>
          <span class="l">“You take the high notes; I’ll keep to the drill.”</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">03</span><span class="cap">the miller</span></div>
        <div class="verse">
          <span class="l">There once was a Bill from the mill,</span>
          <span class="l">Who miscounted the yarn he would sell;</span>
          <span class="l">He tangled the thread,</span>
          <span class="l">And he wept like he’d wed,</span>
          <span class="l">Then cursed, and recounted from hell.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">04</span><span class="cap">the farmer</span></div>
        <div class="verse">
          <span class="l">A Bill from the hill</span>
          <span class="l">Who could not, for his life, keep still;</span>
          <span class="l">He’d swat at a fly,</span>
          <span class="l">Then sit down and sigh,</span>
          <span class="l">While it landed on him — that’s its thrill.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">05</span><span class="cap">the shopper</span></div>
        <div class="verse">
          <span class="l">A Bill from the mall</span>
          <span class="l">Whose cart came off the wall;</span>
          <span class="l">It cycled the aisle</span>
          <span class="l">With his socks for a while —</span>
          <span class="l">Every pair rolled away, by the stall.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">06</span><span class="cap">the baker of Bruges</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Bruges,</span>
          <span class="l">Who baked a great loaf in a mug;</span>
          <span class="l">He sang to the crust,</span>
          <span class="l">“You will trust” —</span>
          <span class="l">But the loaf fell right out of the rug.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">07</span><span class="cap">the lassoer</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Cheyenne,</span>
          <span class="l">Who lassoed the stars with his twine;</span>
          <span class="l">The loop caught a comet,</span>
          <span class="l">He yanked it, then —</span>
          <span class="l">It swung him clean over the plain.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">08</span><span class="cap">the angler</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Cleveland,</span>
          <span class="l">Who polished till every fish had fled;</span>
          <span class="l">He’d holler, “You scallywags!”</span>
          <span class="l">But the lake, with a laugh,</span>
          <span class="l">Just gave back all the silt that he’d shed.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">09</span><span class="cap">the brewer</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Dublin,</span>
          <span class="l">Who brewed up a stout for a shillin’ a tin;</span>
          <span class="l">The bishop said, “Drink!”</span>
          <span class="l">The priest said, “Don’t sink!”</span>
          <span class="l">And Bill, with a grin, said, “One more, then I’m in!”</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">10</span><span class="cap">the vine-swinging fellow</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Rio</span>
          <span class="l">Who swung from a vine with a “Bye-o, bye-o!”</span>
          <span class="l">The vine gave a groan —</span>
          <span class="l">And he fell, on his own,</span>
          <span class="l">Into a barrel of guava: “Eh, that’s a fair blow.”</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">11</span><span class="cap">the topper</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of London,</span>
          <span class="l">Who walked with his hat firmly donned;</span>
          <span class="l">He bowed to a duck,</span>
          <span class="l">The duck said, “You’re stuck!”</span>
          <span class="l">Then they waddled off, side by side, down to the dock.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">12</span><span class="cap">the skier</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Oslo,</span>
          <span class="l">Who skied down the slope at a steady “slow, slow, slow!”</span>
          <span class="l">He soared off the jump,</span>
          <span class="l">With a swoop — and a thump,</span>
          <span class="l">And he said, as the snow settled, “Now that’s the show.”</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">13</span><span class="cap">the cat-keeper</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Prague,</span>
          <span class="l">Who kept a small cat in a mug;</span>
          <span class="l">The cat mewed, “I’m snug!”</span>
          <span class="l">Then it burst out, and flung</span>
          <span class="l">Every hair on the parlor rug.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">14</span><span class="cap">the fig merchant</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Tunis</span>
          <span class="l">Who traded his figs for buns;</span>
          <span class="l">The merchant said, “Fun?”</span>
          <span class="l">And Bill said, “Two for one,”</span>
          <span class="l">And they haggled till sundown, by the figs, and by the sums.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">15</span><span class="cap">the bettor</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Zurich</span>
          <span class="l">Who bet his best friend on the ditch;</span>
          <span class="l">Then got a fright</span>
          <span class="l">From the witch in that plight —</span>
          <span class="l">The friend paid the bet, and he got rich.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">16</span><span class="cap">the pear-slicer</span></div>
        <div class="verse">
          <span class="l">A Bill from the town of Nice</span>
          <span class="l">Who sliced every pear in one slice;</span>
          <span class="l">The mice stood in line,</span>
          <span class="l">And he charged them a dime —</span>
          <span class="l">And he sold every crust at a price that was nice.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">17</span><span class="cap">the pie thief</span></div>
        <div class="verse">
          <span class="l">A Bill from the bakery aisle</span>
          <span class="l">Who stole a whole pie, slice by pile;</span>
          <span class="l">The baker chased him down</span>
          <span class="l">With a great pie-frown,</span>
          <span class="l">But Bill ate the whole thing in a smile.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">18</span><span class="cap">the mayor</span></div>
        <div class="verse">
          <span class="l">Old Bill, who was the mayor,</span>
          <span class="l">Who timed the town by his year;</span>
          <span class="l">He counted in caws,</span>
          <span class="l">But the crows broke the laws,</span>
          <span class="l">And cawed, “You’re off by a feather, sir.”</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">19</span><span class="cap">the blacksmith</span></div>
        <div class="verse">
          <span class="l">Young Bill, the blacksmith,</span>
          <span class="l">Who forged a great shoe with a wit;</span>
          <span class="l">He stamped on the anvil</span>
          <span class="l">And sang, “Hot, and fit!”</span>
          <span class="l">And the shoe held the horse through the hail and the grit.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">20</span><span class="cap">the penguin’s guide</span></div>
        <div class="verse">
          <span class="l">A Bill from the zoo</span>
          <span class="l">Who showed the penguin the view;</span>
          <span class="l">The penguin asked, “Who?”</span>
          <span class="l">And Bill said, “The whole crew!”</span>
          <span class="l">The penguin said, “Boo!” — and it dove in the brew.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">21</span><span class="cap">the ploughman</span></div>
        <div class="verse">
          <span class="l">A Bill from the plough</span>
          <span class="l">Who ploughed his furrow in a row;</span>
          <span class="l">The seed said, “Oh, go!”</span>
          <span class="l">And the rain gave a blow,</span>
          <span class="l">And the field came up green — well, I’ll say, “I do know.”</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">22</span><span class="cap">the schoolmaster</span></div>
        <div class="verse">
          <span class="l">A Bill who taught in the school,</span>
          <span class="l">Who graded the essays with rule;</span>
          <span class="l">The class broke out, “Haha!”</span>
          <span class="l">And Bill sang, “Ra-ra!”</span>
          <span class="l">Gave every one an A — “You’re all just as cool.”</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">23</span><span class="cap">the testator</span></div>
        <div class="verse">
          <span class="l">A Bill who wrote the will,</span>
          <span class="l">Who left the whole farm to the quill</span>
          <span class="l">Of a cat named Jill;</span>
          <span class="l">The heirs cried, “Not fair, Bill!”</span>
          <span class="l">And the cat, with a trill, signed it — and kept the will.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">24</span><span class="cap">the clockmaker</span></div>
        <div class="verse">
          <span class="l">A Bill who built the clock,</span>
          <span class="l">Who wound it up, with a knock;</span>
          <span class="l">It ticked, just one,</span>
          <span class="l">Then it ticked, and two —</span>
          <span class="l">And the whole street stood there, in their socks, in a flock.</span>
        </div><span class="tag">now reading</span>
      </li>

      <li class="lim">
        <div class="lim-head"><span class="no">25</span><span class="cap">the lighthouseman</span></div>
        <div class="verse">
          <span class="l">A Bill from the lighthouse,</span>
          <span class="l">Who kept the great lamp, burning bright;</span>
          <span class="l">The fog came, all white,</span>
          <span class="l">And the sailors, in the night,</span>
          <span class="l">Saw the beam through the dark — what a sight.</span>
        </div><span class="tag">now reading</span>
      </li>
    </ol>

    <footer class="colo">
      <div class="rule-double"></div>
      <p class="colo-text">
        <span class="fin">✦ &nbsp;Fin&nbsp; ✦</span>
        set down by an amateur <span class="k">economist</span> · first told by <span class="k">jurgen</span>
        at the green anchor · a <span class="k">bill</span> of mirth in twenty-five verses ·
        printed, unashamed, on the broadside press of the bill almanack
      </p>
    </footer>
  </main>

  <div class="now" id="now" aria-live="polite"><span class="lbl">Now reading</span> <b>Nº 01</b> <span class="c">the economist</span></div>

<script>
(function(){
  var reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  var items = Array.prototype.slice.call(document.querySelectorAll('.lim'));

  /* ticker fill (two identical halves for a seamless loop) */
  var names = "BILL ✦ BILLY ✦ WILLIAM ✦ WILBUR ✦ WILHELM ✦ BILL THE THIRD ✦ MR. WILL ✦ OLD BILL ✦ YOUNG BILL ✦ DR. BILL ✦ BILL JR. ✦ THE GREAT BILL ✦ BILLY RAGS ✦ BILL THE BRILLIANT ✦ A BILL OF MIRTH ✦ ";
  var seq = '<span class="tt">' + names.replace(/BILL\b/g,'<b>BILL</b>') + '</span>';
  document.getElementById('track').innerHTML = seq + seq;

  /* scroll reveal with per-line cascade */
  if (reduce || !('IntersectionObserver' in window)) {
    items.forEach(function(el){ el.classList.add('in'); });
  } else {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
      });
    }, { threshold:.16, rootMargin:'0px 0px -8% 0px' });
    items.forEach(function(el){ io.observe(el); });

    /* now-reading chip */
    var now = document.getElementById('now');
    var io2 = new IntersectionObserver(function(entries){
      entries.forEach(function(e){
        if (e.isIntersecting){
          var no = e.target.querySelector('.no').textContent;
          var cap = e.target.querySelector('.cap').textContent;
          now.innerHTML = '<span class="lbl">Now reading</span> <b>Nº ' + no + '</b> <span class="c">' + cap + '</span>';
        }
      });
    }, { rootMargin:'-45% 0px -45% 0px', threshold:0 });
    items.forEach(function(el){ io2.observe(el); });
  }

  /* progress + watermark parallax */
  var bar = document.getElementById('progress'), wm = document.getElementById('wm'), tick = false;
  function onScroll(){
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';
    if (!reduce) wm.style.transform = 'translateY(' + (h.scrollTop * -0.05) + 'px)';
    tick = false;
  }
  window.addEventListener('scroll', function(){ if(!tick){ requestAnimationFrame(onScroll); tick = true; } }, { passive:true });
  onScroll();

  /* deal me a Bill */
  var deal = document.getElementById('deal'), dealt = document.getElementById('dealt');
  var count = 0, now = document.getElementById('now');
  deal.addEventListener('click', function(){
    count++; dealt.textContent = count;
    var i = Math.floor(Math.random() * items.length);
    var el = items[i];
    if (now) now.innerHTML = '<span class="lbl">Now reading</span> <b>Nº ' + el.querySelector('.no').textContent + '</b> <span class="c">' + el.querySelector('.cap').textContent + '</span>';
    el.scrollIntoView({ behavior: reduce ? 'auto' : 'smooth', block: 'center' });
    setTimeout(function(){
      document.querySelectorAll('.lim.picked').forEach(function(x){ if (x !== el) x.classList.remove('picked'); });
      el.classList.remove('picked'); void el.offsetWidth; el.classList.add('picked');
      setTimeout(function(){ el.classList.remove('picked'); }, 1600);
    }, reduce ? 0 : 420);
  });
})();
</script>
</body>
</html>
